import {games,gameById} from './catalog.js';import {escapeHTML as esc,formatTime,downloadJSON} from './ui.js';import {loadHistory,browserStorage,priorHistory,summarize,HISTORY_KEY} from './history.js';
const rate=r=>r.elapsed>0?r.correct*60/r.elapsed:0;
function baselineText(past,current){const s=summarize([...past,current]);if(s.baseline===null)return 'Answer a round to establish your baseline.';if(!s.repeat)return `First scored attempt: ${s.baseline.toFixed(1)} correct/min. This is your baseline.`;return `First-attempt baseline: ${s.baseline.toFixed(1)} correct/min. ${s.improvement===null?'Your baseline was zero, so percentage change is not defined.':`Latest attempt: ${s.improvement>0?'+':''}${s.improvement}% compared with that baseline.`}`;}
const tips={numerosity:'Look for pairs that complement the target before trying larger combinations.',digitspan:'Try grouping characters into pairs. Accuracy comes before a longer sequence.',flashback:'Keep a rolling mental queue. Replace the oldest item after every comparison.',disconumbers:'Recall the positions first, then reconstruct the sum from the sequence.',pathfinder:'Start at the entrance. Check that every neighboring tile connects on both sides.',puzzle:'Use the large circle and diagonal edges as anchors, then fill in neighboring pieces.',shapedance:'Compare the color order and small details. Pause rotation while learning, then try matching in motion.',singularity:'Use a steady row-by-row scan instead of jumping between symbols.',pulse:'Keep a steady posture. Wait for the target rather than anticipating it.',emotions:'Notice the eyes, eyebrows, and mouth together. These illustrations use simplified cues.'};
function metrics(r){const list=[];if(Number.isFinite(r.metrics.span))list.push(['Longest recalled sequence',r.metrics.span]);if(Number.isFinite(r.metrics.nBack))list.push(['Items back',r.metrics.nBack]);if(r.gameId==='pulse'){list.push(['Targets caught',r.metrics.hits||0],['Missed targets',r.metrics.misses||0],['False alarms',r.metrics.falseAlarms||0],['Correct holds',r.metrics.correctHolds||0]);if(Number.isFinite(r.metrics.reactionMs))list.push(['Mean target response',r.metrics.reactionMs+' ms']);}return list.map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('');}
function reflections(r){const responses=Array.isArray(r.metrics.responses)?r.metrics.responses:[];return `<div class="reflection-summary"><h2>A snapshot of your preferences</h2><p>These are the choices you made today. They are not personality diagnoses or a prediction of job fit.</p>${responses.length?`<details open><summary>Your ${responses.length} responses</summary>${responses.map(x=>`<div class="response-review"><p>${esc(x.prompt||'')}</p><strong>${esc(x.choice||'')}</strong><span>${esc(x.trait||'')}</span></div>`).join('')}</details>`:'<p>No responses recorded yet.</p>'}</div>`;}
export function showResults(main,r,warning=''){const g=gameById(r.gameId),past=priorHistory(loadHistory(browserStorage()).records,r),best=past.length?Math.max(...past.map(rate)):null;const accuracy=r.attempts?Math.round(r.correct/r.attempts*100):null;main.innerHTML=`<section class="results"><a class="back" href="#library">All games</a><div class="result-heading"><div><span class="category">${g.name} · ${r.mode==='learn'?'Learning':'Timed'} · ${esc(r.difficulty)}</span><h1>One more practice<br>in the bank.</h1><p>${r.scored?'Here’s how this session went. Your next attempt starts from here.':'A little time to understand how you work.'}</p></div><div class="result-seal" aria-hidden="true"><svg viewBox="0 0 80 80"><circle cx="40" cy="40" r="35" fill="#e6f2ed"/><path d="m24 40 11 11 22-24" fill="none" stroke="#25896d" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></svg></div></div>${warning?`<p class="warning" role="status">${esc(warning)}</p>`:''}${r.scored?`<div class="result-stats"><div><span>Accuracy</span><strong>${accuracy===null?'—':accuracy+'%'}</strong><small>${r.correct} correct / ${r.attempts} answered</small></div><div><span>Correct per minute</span><strong>${rate(r).toFixed(1)}</strong><small>Includes all session time</small></div><div><span>Practice time</span><strong>${formatTime(r.elapsed)}</strong><small>${r.mode==='learn'?'At your own pace':'Timed practice'}</small></div></div><div class="detail-metrics">${metrics(r)}</div><div class="result-panels"><div><h2>Your own benchmark</h2><p>${!r.attempts?'Complete some rounds to establish a baseline.':best===null?'This is your first session with these settings. Repeat it to start comparing your progress.':`Your previous best was <strong>${best.toFixed(1)} correct/min</strong> across ${past.length} comparable ${past.length===1?'session':'sessions'}. ${rate(r)>best?'You set a new personal best.':'Keep accuracy steady as you build familiarity.'}`}</p><p class="baseline-note">${baselineText(past,r)}</p><span class="subtle">Same game, mode, difficulty, and scoring version.</span></div><div><h2>For your next attempt</h2><p>${tips[r.gameId]}</p>${r.mode==='learn'?'<span class="subtle">Learning pace includes time spent reading feedback. Use timed mode for steadier speed comparisons.</span>':''}</div></div>`:reflections(r)}<div class="actions"><a class="primary" href="#game/${g.id}">Practice again</a><a class="secondary" href="#progress">View my progress</a><button id="export-result">Export this result</button></div><p class="fine-print">Practice results use this app’s rules. They are not official HireVue scores.</p></section>`;main.querySelector('#export-result').onclick=()=>downloadJSON(r,`${g.id}-practice-result`);}
export function showProgress(main){const {records,warning}=loadHistory(browserStorage());if(!records.length){main.innerHTML=`<section class="empty"><span class="empty-graphic" aria-hidden="true"><svg width="100" height="70" viewBox="0 0 100 70"><path d="M10 60h80M20 45l20-15 20 8 20-27" fill="none" stroke="#9fb5db" stroke-width="4" stroke-linecap="round"/><circle cx="80" cy="11" r="6" fill="#245de8"/></svg></span><h1>Your progress starts<br>with a game.</h1><p>Every completed session is a new point of reference.<br>Practice a game to start your personal history.</p>${warning?`<p class="warning">${esc(warning)}</p><button id="reset-history">Reset unreadable history</button>`:''}<a class="primary" href="#library">Explore the games</a></section>`;main.querySelector('#reset-history')?.addEventListener('click',()=>clearHistory(main));return;}
 const available=games.filter(g=>records.some(r=>r.gameId===g.id));main.innerHTML=`<section class="progress-page"><div class="progress-heading"><div><h1>Your practice, over time.</h1><p>A record of your attempts. A clearer picture of your progress.</p></div><button id="export-all">Export history</button></div>${warning?`<p class="warning">${esc(warning)}</p>`:''}<div class="progress-controls"><label>Game<select id="history-game">${available.map(g=>`<option value="${g.id}">${g.name}</option>`).join('')}</select></label><label>Mode<select id="history-mode"><option value="timed">Timed</option><option value="learn">Learning</option></select></label><label>Difficulty<select id="history-difficulty"><option value="easy">Easy</option><option value="standard" selected>Standard</option><option value="hard">Hard</option></select></label></div><div id="progress-content"></div><div class="history-foot"><p>Saved in this browser only. Export your history before clearing browser data.</p><button id="clear-history">Clear history</button></div></section>`;
 const last=records.at(-1);main.querySelector('#history-game').value=last.gameId;main.querySelector('#history-mode').value=last.mode;main.querySelector('#history-difficulty').value=last.difficulty;
 function update(){const id=main.querySelector('#history-game').value,mode=main.querySelector('#history-mode').value,difficulty=main.querySelector('#history-difficulty').value;const subset=records.filter(r=>r.gameId===id&&r.mode===mode&&r.difficulty===difficulty&&r.version===gameById(id).version).sort((a,b)=>a.timestamp-b.timestamp),summary=summarize(subset),g=gameById(id);const content=main.querySelector('#progress-content');if(!subset.length){content.innerHTML='<div class="inline-empty"><h2>No sessions with these settings yet.</h2><p>Try another mode or difficulty, or start a new practice.</p></div>';return;}const max=Math.max(1,...subset.map(rate)),shown=subset.slice(-20);content.innerHTML=`<div class="progress-summary"><span><strong>${subset.length}</strong> ${subset.length===1?'session':'sessions'}</span>${g.scored?`<span><strong>${summary.accuracy===null?'—':summary.accuracy+'%'}</strong> overall accuracy</span><span><strong>${summary.best===null?'—':summary.best.toFixed(1)}</strong> best correct/min</span>`:'<span>Your responses are reflections, not scores.</span>'}</div>${g.scored?`<p class="baseline-note">${baselineText(subset.slice(0,-1),subset.at(-1))}</p><div class="chart-panel"><div class="section-heading"><h2>Correct answers per minute</h2><span>Most recent ${shown.length} sessions</span></div><div class="bar-chart" role="img" aria-label="Your recent session rates: ${shown.map((r,i)=>`session ${i+1}, ${rate(r).toFixed(1)} correct per minute`).join('; ')}">${shown.map((r,i)=>`<div class="bar-column"><span>${rate(r).toFixed(1)}</span><div class="bar-track"><div class="bar" style="height:${Math.max(2,rate(r)/max*100)}%"></div></div><small>${subset.length-shown.length+i+1}</small></div>`).join('')}</div><p class="subtle">Session number · Same game settings and scoring version${mode==='learn'?' · Learning time includes reading feedback':''}</p></div>`:''}<div class="history-list"><h2>Session history</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>${g.scored?'Accuracy':'Responses'}</th><th>Time</th><th>Details</th></tr></thead><tbody>${[...subset].reverse().map(r=>`<tr><td>${new Date(r.timestamp).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</td><td>${g.scored?(r.attempts?Math.round(r.correct/r.attempts*100)+'%':'—'):r.attempts}</td><td>${formatTime(r.elapsed)}</td><td><button class="text-button" data-result="${esc(r.id)}">View result</button></td></tr>`).join('')}</tbody></table></div></div>`;content.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{showResults(main,records.find(r=>r.id===b.dataset.result));window.scrollTo(0,0);});}
 main.querySelectorAll('select').forEach(s=>s.onchange=update);main.querySelector('#export-all').onclick=()=>downloadJSON(records);main.querySelector('#clear-history').onclick=()=>clearHistory(main);update();}
function clearHistory(main){const dialog=document.createElement('dialog');dialog.innerHTML='<h2>Clear your practice history?</h2><p>This removes saved sessions from this browser. Export your history first if you want to keep a copy.</p><div class="actions"><button id="cancel-clear">Keep history</button><button id="confirm-clear" class="danger">Clear history</button></div>';document.body.append(dialog);dialog.showModal();dialog.querySelector('#cancel-clear').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.querySelector('#confirm-clear').onclick=()=>{try{browserStorage().removeItem(HISTORY_KEY);dialog.close();showProgress(main);}catch{dialog.querySelector('p').textContent='This browser could not clear the history. Check your browser storage settings.';}};}
